          "title": "吕超4月起任合规风控等职；离开原高管岗位与跨机构任职分阶段发生",
          "summary": "添佑私募的协会公示显示，吕超自2026年4月起担任合规风控负责人、信息填报负责人及风控总监。其同页履历记录：2023年7月至2025年11月在博汇康宁任上述三项职务，随后在该机构任风控专员至2026年2月，2026年4月在添佑有风控专员及现任职务记录；日期仅披露到月，无法确定日级生效顺序。博汇康宁另一份公示显示何雨歆2025年11月起担任三项风控职务。因此，吕超2025年11月结束原高管任期，不等于当月即离开该机构。",
          "stage": "任职已公示／生效日期精确到月",
          "coverage": "研究截止2026-09-21。用添佑与博汇康宁两份当前公示中的明确历史履历，核查2023-07至2026-04的相关任职衔接；不是持有历次网页快照。添佑页面最后更新时间2026-08-18，博汇康宁为2025-12-25；不能把该更新时间当任职日或首次披露日。公开履历仅精确到月，前任高管终止职务不等于同时离职。劳动关系、交接日、任职原因及整改结论未取得，不影响已公示职务及历史任职边界的确认。",
          "occurredAt": "2026年4月起任职；公开履历只精确到月",
          "publishedAt": "2026-09-21T14:34:52+08:00",
          "updatedAt": "2026-09-21T14:34:52+08:00",
          "researchCutoff": "2026-09-21",
          "disclosureLabel": "管理人公示页最后更新时间；不是任职生效日",
