          "time": "",
          "title": "西北有色院拟减持不超623.68万股，窗口为5月11日至8月11日",
          "summary": "西部超导控股股东西北有色金属研究院披露，拟于2026年5月11日至8月11日通过集中竞价或大宗交易合计减持不超过6,236,779股、占公司总股本不超过0.96%，用于加强科研投入及创新中心建设。披露时持股136,151,200股、占20.96%；计划尚未开始，是否实施、实际数量和价格均不确定。本段保存4月15日披露时点的事实，后续执行见同一事件8月12日结果。[来源1]",
          "stage": "拟实施",
          "coverage": "历史快照：本次内容按2026-04-15已披露资料重建；未把8月实际成交倒写进4月正文。页面制作/复核截止2026-09-21。",
          "occurredAt": "拟2026-05-11至2026-08-11",
