          "summary": "铂力特披露已完成2024年11月27日董事会批准的第二轮回购，累计购入1,759,549股、支付73,212,663.63元（不含交易费用），成交价38.42—50.44元/股。实际支出处于7,000万元至1亿元的计划区间内，用途为维护公司价值及股东权益。连同此前532,360股，公司回购专户共持有2,291,909股。本轮资金来源为自有及自筹资金，原方案期限为董事会通过起3个月内，后续安排为披露结果12个月后出售；本段为当时披露快照。[来源1、来源2]",
