          "summary": "陕鼓动力2021年限制性股票激励计划首次授予部分第三期共有637人符合解除限售条件，14,779,888股拟于2026年9月24日上市流通，约占公告时总股本0.86%。本次是2021年已经缴款登记股份的解锁，不是新增授予或员工再次认购；截至本稿9月21日研究截止，9月24日尚未到来，不能写为已上市或已出售。公司同时回溯，2021年计划中因离职、岗位职级或绩效等原因被回购的1,607,622股已于9月10日注销；这部分与本次解锁数量分开处理。[来源1]",
