          "summary": "烽火电子披露，向长岭电气、金创和信、陕西电子收购长岭科技98.3950%股权的过户手续已于2025年3月21日前完成，146,840,727股对价股份拟于4月8日上市。合同对价合计约11.47亿元，其中2.5亿元现金全部付给长岭电气，其余以股份支付。截至本次公告出具日，现金对价尚未支付；不超过8.9亿元配套募资也仍待实施。这一节点是资产交割及新股上市安排，并非所有价款均已到账。[来源1]",
          "stage": "资产交割完成／新股待上市",
          "coverage": "历史节点按2025年4月2日公告当时披露整理；没有把2026年获知的付款、限售或补偿结果倒填进本节点。后续核实结果请看同一事件2026年8月28日节点。",
          "occurredAt": "截至2025年3月21日完成股权过户；计划2025年4月8日新股上市",
          "publishedAt": "2026-09-21（真实资料样稿编写日，非历史发布日）",
          "updatedAt": "2026-09-21",
          "researchCutoff": "2026-09-21",
          "disclosureLabel": "资料披露日",
