            "note": "仅修订历史时间线：原2025-04-08节点合写对价股份上市与随后6月配套发行、到账，现拆为4月8日、6月4日及截至6月10日三个节点。6月4日为年报表列发行日期，6月10日为年报所称发行完成日及验资到账截止日；未把“截至”改成精确转账日。本次动态正文、原资料披露日和研究截止保持不变，原历史文本保留供复核。",
            "previousSummary": "烽火电子2026年半年报显示，收购长岭科技的现金对价项目累计投入25,000万元，完成该项承诺投入额，2026年上半年新增投入为零；这不是当期新增2.5亿元可投资资金。售股股东金创和信获配的59,851,239股已解除限售，另两名售股股东所获对价股份仍在限售表内。交易还进入业绩补偿阶段：6月5日公告拟以总价1元回购注销长岭电气、陕西电子合计868,395股；已取得材料未提供注销完成依据，不能表述为已注销。[来源1、来源4]",
            "previousHistory": [
              {
                "date": "2023-09-30",
                "text": "以该日为原评估基准，长岭科技98.3950%股权约定交易价114,719.68万元。交易采用现金＋发行股份，同为集团体系内的关联交易。[来源2]"
              },
              {
                "date": "2025-04-08",
                "text": "股权过户后，146,840,727股对价股份上市。随后配套发行114,249,034股，价格7.79元/股，募集总额889,999,974.86元、净额870,013,466.61元；承销费扣除后的资金于6月10日前到账。8.9亿元上限因此有了实际发行结果，但总额与净额不可混用。[来源3]"
              },
              {
                "date": "2026-04-29",
                "text": "首次披露2025年度补偿：专项承诺涉及专利收益与房地产减值，不等于对长岭科技全部净利润承诺。专利实际收益2,254.14万元，低于承诺2,686.91万元，完成83.89%；另有房地产减值，形成两类补偿。[来源5、来源3]"
              },
              {
                "date": "2026-06-05",
                "text": "股东会批准后的债权人通知明确拟按总价1元注销868,395股。该次通知是补偿执行环节，不是二级市场回购计划；公告债权申报窗口为历史窗口。[来源4]"
              },
              {
                "date": "2026-08-28",
                "text": "半年报确认现金对价项目累计投入2.5亿元，金创和信59,851,239股期末限售为零。解除限售只改变可流通状态，不代表有减持计划或已卖出。[来源1]"
              }
            ]
