          "title": "募集资金现金管理授权降至6,000万元，自有资金上限维持2亿元",
          "summary": "西安西测测试技术股份有限公司（301306.SZ）于2026年9月18日经第三届董事会第九次会议批准，公司及控股子公司可使用不超过6,000万元闲置募集资金和不超过20,000万元闲置自有资金进行现金管理，两类额度均含本数，自董事会审议通过之日起12个月内循环使用。募集资金上限较2025年9月18日授权减少4,000万元、下降40%，自有资金上限不变。截至2026年9月16日，公司披露募集资金余额6,330.31万元，其中前次现金管理未到期金额为0万元，其余存于募集资金专户。上述数字分别是授权上限、募集资金余额及未到期存量，不能表述为已投入2.6亿元或新增可争取资金。历史上存在具体现金管理交易；2026年半年度披露累计取得现金管理收益5.64万元，期末募集资金理财未到期金额为0万元，零存量不代表期间没有交易。研究截止为2026年9月23日15:20:12（北京时间），本轮补取的历史材料均在该截止前公开。",
          "stage": "董事会已批准",
          "depth": "deep",
          "coverage": "本事项有限历史研究；不等于观察池全量已更新。近一年完整逐笔交易与资金性质拆分；2025年9月18日至研究截止日，募集资金和自有资金分别对应的完整购买、赎回、机构、期限、到账收益及累计购买流水。 2025年末两项产品的机构、期限及到账收益；实际销售或交易机构、具体产品代码、购买日、起息及到期日、资金来源、赎回及实际到账收益。 2024年两笔产品的实际到账明细；两笔各自实际到账收益、具体赎回到账日期、实际收回金额及购买指令日期。 2026年半年度收益缺少逐笔拆分；每笔机构、产品名称或代码、金额、期限、赎回及到账收益。 年度汇总已核验，逐笔对应及冻结后续仍有缺口；已核页面未解释资产出售与现金赎回差额原因；未提供冻结资金逐笔归属、解冻或成交进展及研究截止状态；2025年9月18日起近一年完整流水及募集／自有拆分仍缺。 前次单独授权文件及2024年股东大会确切日期；2025年单独现金管理授权公告及2024年对应股东大会决议原件。 本次授权后的成交及研究截止时的实际余额；2026年9月18日授权之后至研究截止的具体成交、赎回及最新可配置余额。",
          "occurredAt": "2026-09-18董事会审议通过；授权不等于购买完成",
