          "title": "黄陵店头电厂二期首台百万千瓦机组投产",
          "summary": "陕煤集团9月16日披露，黄陵矿业沮源发电公司2×1000MW发电项目1号机组于当日9时58分通过168小时试运行、正式移交生产；9月18日集团报道明确其为店头电厂二期项目。本次进展是首台百万千瓦机组进入生产阶段，已查材料尚未确认二期双机全部投产。历史环评追述项目于2022年10月核准；2026年5月22日出具的评级报告列示，截至2025年末，该项目预算81.56亿元、工程进度23.00%，均不能作为当前实际投资或当前工程进度。2023年环评静态、动态投资估算及2026年4月报道的阶段性概算节余属于不同口径，不能相减生成投资节约或可用现金。集团所称年发电量110亿千瓦时、年产值约40亿元为全项目建成后预期，首台实际经营贡献、项目当前股权链及融资安排仍待进一步证据。",
          "stage": "首台机组通过168小时试运行并移交生产",
          "depth": "deep",
          "coverage": "本事项有限历史研究；不等于观察池全量已更新。准确开工日及施工周期；明确项目准确开工日的原件，以及点火报道所称18个月施工周期的起止定义或更正。 首次并网日期；https://www.shccig.com/index/Article/index.html?id=1429633&cid=26 的有效文章正文。 当前法律主体及完整股权链；沮源发电工商全称、截至研究截止的直接及最终股东、各层持股比例及相关变更文件。 当前实际投资、决算及融资安排；当前批准概算及调整明细、累计实际投资、竣工决算、资本金与债务来源、贷款余额、期限、担保、还款安排，以及项目与相关债券资金用途的对应披露。 环评静态单位投资不一致；静态总投资820918万元与表列3949元/kW之间的口径解释或正式更正。 累计发电量统计范围；3.8亿千瓦时累计发电量的统计起止时间及范围。 第二台投产及实际经营贡献；二期第二台机组正式投产证明，以及首台实际售电量、电费结算、营业收入和利润。",
