              "text": "2023年10月环评追述，陕西省发展改革委以陕发改能电力〔2022〕1856号核准店头电厂二期2×1000MW机组扩建工程。未取得单独核准批复原件，日期保留到月；该信息不表述为本轮已经核验2022年原始披露。"
