              "text": "2026年5月22日出具的评级报告追述，自2024年10月起，陕西黄陵发电、黄陵煤矸石、沮源发电划入电力集团合并。这是历史合并口径信息，未据此认定股权转让比例、当前直接股东或完整股权链。"
