              "text": "集团披露一季度建设进展：锅炉补给水系统成功制水、1号锅炉水压试验通过、1号机组DCS系统受电完成。报道同时称前期工程结算、主体工程及主辅机合同签订等较批复概算节余2.89亿元，未给出全项目最终决算。"
