          "business": [
            "经营理解：首台机组由建设调试转入生产，后续应观察实际售电量、结算电价、燃料成本、机组可用率及经营回款。历史环评中的矿区供煤和既有设施利用为煤电协同提供方案依据，现有资料尚不能量化新增利润。",
            "营业部服务：可围绕首台投产更新企业经营阶段，向企业核实沮源发电、黄陵矿业及电力集团各自的经营、资金管理和授权职责。2026年5月22日出具的评级报告记载，集团通过本部结算中心和陕煤财务公司集中管理资金：前者主要归集本部给予内部贷款的子公司资金，后者按要求归集上述子公司之外的内部资金。该集团层面历史安排是否具体适用于沮源发电，当前资金归集、授权职责及既有服务安排仍需向客户确认；不能据投产、预算或概算节余推定项目存在可自主支配的闲置资金。现金管理或其他证券服务须以资金性质、实际权限和客户需求为前提。",
            "投行事项：如果实际融资主体确认存在建设收尾融资或存量债务调整需求，才可进一步讨论资金用途、债务期限、担保及偿还来源。已查评级报告没有证明该期债券募集资金用于店头二期，不能将集团债券名称转化为本项目已融资事实或待承销需求。",
            "信用背景：评级报告在其披露时点指出集团资本支出较大、财务杠杆较高、债务负担偏重，同时认为煤炭主业获现能力和外部融资能力支持偿债。上述评价属于集团层面历史背景，不能直接替代项目公司的信用判断。进一步讨论须结合当前股权关系、融资主体和已落实的服务安排。"
          ],
