          "summary": "北方光电股份有限公司（600184）9月18日披露，9月17日股东会通过续聘2026年度审计机构议案。结合8月28日续聘公告，受聘机构为立信会计师事务所（特殊普通合伙），服务范围为2026年度财务报告及内部控制审计；审计费用拟定36万元，其中财务报告审计25万元、内控审计11万元，不含审计期间食宿费用，较上一期收费无变化。按此前公告约定，聘任事项自股东会审议通过之日起生效；现有材料不能证明服务合同已签署或费用已支付。",
