            "facts": "9月17日股东会通过2026年度审计机构续聘议案，聘任事项按公告约定当日起生效。财务报告及内控审计费用合计拟定36万元，不含审计期间食宿费用，较上一期无变化；合同签署及付款情况未披露。"
