          "time": "",
          "title": "研发中心项目获准结项，拟将节余1,700.77万元永久补流",
          "summary": "爱科赛博2026年9月29日披露，董事会于9月28日同意将2023年IPO募投项目“研发中心升级改造项目”结项，并将节余募集资金永久补充流动资金，用于日常生产经营。截至9月23日，该项目承诺使用6,000.00万元，实际使用4,436.83万元，利息及理财收益净额137.60万元，节余1,700.77万元。公司称项目已达到预定可使用状态，节余与新总部资源统筹、采购计划优化、成本控制及利息理财收益有关。拟补流金额以资金转出日专户余额为准，23.72万元合同尾款及增补合同款、质保金等尚未支付。长江证券承销保荐有限公司对此无异议，该事项无需提交股东会审议；截至研究截止，所查材料尚不能证明资金已转出或专户已注销。",
          "stage": "9月28日董事会审议通过结项及永久补流方案，保荐机构无异议；资金转出和销户尚无完成证据",
          "depth": "deep",
          "coverage": "本事项有限历史研究；不等于观察池全量已更新。历史对照限于招股意向书、2024年半年度专项报告、2025年年度报告及本次公告和保荐意见，不构成公司全部历史公告或逐笔资金流水，不能据此断言项目全历史从无其他调整。 本次文件未按原概算五个类别披露最终实际支出，也未量化资源统筹、采购优化和成本控制各自的节余贡献，无法据此重建分类决算。 2025年年报列示四个置换完成日期及合计金额，未拆分各次金额。 截至研究截止，所查材料未提供补流实际转出金额和日期、尾款结清、专户注销及监管协议终止的完成证据。 招股意向书与2025年年度报告的具体披露日期尚未确认，来源日期留空；链接中的日期仅作文件版本定位。 137.60万元为本项目披露的利息及理财收益净额，缺少本项目专属产品逐笔归属及收益拆分，不能用于计算公司全年收益或还原现金管理全历史。",
