              "截至9月23日，项目承诺投入6,000.00万元、实际使用4,436.83万元，计入137.60万元利息及理财收益净额后节余1,700.77万元。",
              "拟补流金额以转出日专户余额为准，23.72万元款项尚未支付；补流完成前由募集资金账户支付，完成后剩余尾款由自有资金支付。截至研究截止2026年9月29日19:41:39，所查材料尚无转出及销户完成证据。"
