          "summary": "康拓医疗2026年9月15日股东会通过向参股公司BRANCHPOINT & AURA DEVELOPMENT LLC提供财务资助的议案，决议于9月16日披露。根据8月28日专项公告，公司拟以自有资金通过全资子公司TIOGA提供不超过200万美元借款，年利率5%，期限自股东会通过之日起不超过一年，额度可循环使用，无担保，用于支持无线颅内压监护仪量产上市及国内注册。公司将其解释为此前股权投资暂缓履约的过渡安排：公告列示TIOGA持股39.55%，此前拟投资的200万美元截至公告披露日尚未完成，44.79%为投资完成后的拟持股比例。双方已有商品采购、劳务和借款往来；受助方2026年上半年仍亏损，其他股东未同比例提供资助，康拓医疗半年报亦披露相关应收项目坏账准备。本次核实阶段为股东会批准，所查材料没有本次实际放款证明。",
