          "stage": "增资相关工商变更及章程备案完成，取得换发营业执照",
          "depth": "deep",
          "coverage": "本事项有限历史研究；不等于观察池全量已更新。原增资公告及进展公告未披露各股东本轮实际缴付金额、到账日期、具体缴款期限及支付条件；本稿只确认方案与工商变更，不判断资金已经全部到账或尚未支付。 原公告披露江苏功成新增870万元、北农华不新增出资，但未进一步说明两者的资金来源、支付安排或优先认缴权处理文件；不据此推断其放弃权利的具体程序。 财务表对营业收入和净利润未另列明确期间，已保留原始列头，未作同比或年化分析；此项不影响权益结构及工商进展判断。 相关历史覆盖2022年摘要记载的设立与三次股权变更，以及2026年本轮公告；未完成2022年摘要签署日至本轮增资之间的全部资本变化核查，不能表述为完整历史或期间从未变动。 9月29日进展公告实际取得时间为10:32:18，晚于来源发现截止10:31:57；留存证据不能证明该公告在更早分钟截止前已经公开。本文采用已留存原件，不推进原发现窗口。",
