          "history": [
            {
              "date": "2022-07-18",
              "text": "本轮补入的招股说明书摘要回溯：一简一至于2019年12月23日成立，设立时江苏功成认缴1,000万元、持股100%；2020年10月新增注册资本1,060万元由北农华认缴，注册资本增至2,060万元。该节点为2022年材料中的历史回溯。"
            },
            {
              "date": "2022-07-18",
              "text": "同份摘要回溯2020年12月上格之路入股：承担受让自北农华的860万元未实缴认缴出资，另认缴新增注册资本7,940万元，投资额合计8,800万元，持股88%。摘要记载验资报告确认，截至2020年12月22日一简一至收到全体股东实缴出资10,000万元；12月28日领取新营业执照。860万元为承担实缴义务的出资额，不能直接写成支付给售股股东的现金对价。"
            },
            {
              "date": "2022-07-18",
              "text": "同份摘要回溯2021年11月一简一至新增注册资本5,000万元，上格之路、江苏功成、北农华分别认缴4,400万元、500万元、100万元，12月7日领取新营业执照。变更后出资表列示三方认缴和实缴分别为13,200万元、1,500万元、300万元，持股88%、10%、2%。该历史结构与2026年原增资公告列示的增资前结构一致，但不能据此推断期间从未发生资本变化。"
            },
            {
              "date": "2026-09-11",
              "text": "董事会决议披露，9月10日召开的第三届董事会第七次会议通过本次增资议案，同意9票、反对0票、弃权0票，议案已经董事会战略委员会审议通过。"
            },
            {
              "date": "2026-09-11",
              "text": "原增资公告披露完整方案：上格之路新增出资14,130万元、江苏功成新增870万元、北农华新增0元，新增资本合计15,000万元；增资后三方认缴出资分别为27,330万元、2,370万元、300万元，持股91.10%、7.90%、1.00%。公告称该事项已经战略委员会、独立董事专门会议审议通过，上格之路履行了必要内部审批程序，无需提交上市公司股东会审议。"
            },
            {
              "date": "2026-09-29",
              "text": "进展公告披露，一简一至增加注册资本、修订章程及授权办理工商手续事项已获其股东会批准，近日完成登记备案并取得新营业执照，注册资本为30,000万元。具体登记完成日期未披露。"
            }
          ],
          "business": [
            "本轮是既有控股子公司的增资。与2021年三方按原比例认缴相比，2026年方案中上格之路承担更多新增出资，持股比例提高3.10个百分点；江苏功成虽参与增资，持股比例仍下降，北农华未新增出资、比例下降。公司披露合并报表范围不变。",
            "2022年招股说明书摘要将一简一至主营列为农药原药及中间体、农药制剂的研发和生产，当时尚在建设原药生产线。2026年公告将本轮目的表述为支持业务开展和日常经营、优化资本结构，不能将资金用途直接套用为2022年的产线建设项目。",
            "原增资公告列示，一简一至2026年6月30日未经审计总负债为355,728,482.34元、净资产为26,684,870.53元，同列净利润为负数；这使经营资金安排和资本结构改善成为值得跟踪的内容，但尚不能据工商变更认定负债率已经下降或经营改善已经实现。",
            "可向实际出资主体上格之路了解自有与自筹资金的具体构成，向用款主体一简一至了解实缴进度、经营用款节奏及现有融资安排，再判断是否存在证券服务需求。上市公司、出资子公司与用款子公司的服务对象应分别识别；14,130万元不等于可供配置的闲置资金，也不直接证明外部融资需求。"
          ],
