          "summary": "爱科赛博2026年9月29日披露，9月28日股东会通过2026年限制性股票激励计划草案、考核办法及实施授权。方案拟向不超过149人授予400万股第二类限制性股票，约占草案公告时总股本的3.47%，摘要规定授予价格不低于31.20元/股。股份来自公司回购或定向发行，激励对象以自筹资金参与，分三期按30%、40%、30%安排归属。公司层面按营业收入或AIDC测试电源收入考核，分别计算后取较高归属比例。历史上，2024年计划前两期及2025年计划首期均出现业绩未达标作废记录。本次新增阶段为股东会批准，留存材料不能证明2026年计划已经实际授予、归属或上市流通。",
