          "summary": "供销大集2026年9月28日披露，控股股东北京中合农信企业管理咨询有限公司的一致行动人中国供销商贸流通集团有限公司，原计划自6月25日起6个月内通过集中竞价增持人民币3,000万至5,000万元。截至9月24日，因半年报窗口期和自身资金安排等综合因素，供销商贸尚未增持。此前，供销商贸分别取得北京银行、中信银行各最高不超过4,500万元的贷款承诺，但承诺均附条件，现有材料未披露实际提款，也未说明两项承诺的替代或并行关系。公司仍提示资金筹措等因素可能导致计划延迟或无法实施。",
          "stage": "原增持计划时间过半，截至2026年9月24日尚未增持",
          "depth": "deep",
          "coverage": "本事项有限历史研究；不等于观察池全量已更新。核查范围为本事项四份留存公告，不构成全历史覆盖；未联网核查原研究截止后的新增披露。 四份公告未披露最终借款合同、实际提款金额和到账日期，也未说明两家银行承诺的替代或并行关系；因此不合计承诺额度，不推定已获实际融资。 未提供司法拍卖成交、股份过户及最新权益变动原件；本稿仅采用计划实施前持股基线，不将其表述为9月24日或当前持股状态。",
