          "business": [
            "本事项的资金与交易主体为增持股东供销商贸。两家银行已出具附条件的贷款承诺，应先了解现有融资安排、合同签署及提款条件落实情况，再与股东讨论可能需要的交易执行和资金衔接服务；不能把承诺上限视为已到账资金或待争取融资需求。",
            "原计划金额和实施期限未变，截至9月24日仍未增持，后续观察重点是首次实际成交、累计执行金额及资金落实进展。是否需要券商服务、现有证券服务机构及具体执行安排，均待客户确认。"
          ],
