          "title": "陕西友帮预重整延期一个月，债权申报与投资方案仍待推进",
          "summary": "康惠股份2026年9月25日披露，控股子公司陕西友帮收到临时管理人转来的法院批复，预重整期限获准延长一个月。陕西友帮已完成审计评估，仍在与意向投资人沟通确定预重整方案；延期申请提及账面记载的大额债权人尚未申报债权、众多债权人仍需进一步沟通。历史公告显示，截至2026年3月末，陕西友帮资产12,446.54万元、负债43,932.19万元；康惠股份另在5月公告披露对其资金支持及连带责任担保风险。上述历史金额不能作为9月最新余额，延期也不代表正式进入破产重整、投资协议签署或资金到账。",
          "stage": "法院同意预重整期限延长一个月，仍在沟通确定预重整方案",
          "depth": "deep",
          "coverage": "本事项有限历史研究；不等于观察池全量已更新。本次延期公告未披露意向投资人身份、投资金额、最终清偿比例、协议签署或资金到账情况；未披露不能表述为未发生。 本次公告未披露审计评估具体结果，也未更新历史债权、股权投资账面净额及担保余额；本稿不据历史金额推算9月风险敞口或最终损失。 未单独取得公司2026-044号公告及招募网页附件PDF；招募事实已由管理人保存的官方HTML全文支撑，未将未取得文件列为文章来源，也不声称完成全历史覆盖。 未取得原招募日程后续调整及遴选执行结果，故仅列历史安排，不认定原定节点已经完成。 本次只形成待独立核查候选，未执行独立核查或发布。",
