          "history": [
            {
              "date": "2025-10-30",
              "text": "公司披露董事会于10月29日以9票同意、0票反对、0票弃权，同意陕西友帮申请重整并申请启动预重整程序。陕西友帮因长期亏损于2025年9月全面停产，难以清偿到期债务；当时尚待法院受理并裁定。截至2025年9月末，公司对其应收款项25,270.76万元，计提坏账准备12,089.52万元，净额13,181.24万元；长期股权投资235.62万元已全额计提减值。"
            },
            {
              "date": "2026-05-12",
              "text": "公司披露陕西友帮于2025年12月初提交预重整申请材料，法院于2026年5月9日决定进行预重整，并指定陕西仁和万国律师事务所担任临时管理人。决定书明确期限自2026年5月7日起五个月。公司在本次公告披露直接资金支持27,227.53万元、贷款担保余额5,021.32万元，并提示债权受偿、股权投资回收及担保履行风险；进入预重整不代表正式启动破产重整。"
            },
            {
              "date": "2026-06-12",
              "text": "临时管理人发布意向投资人招募公告，原安排为7月20日18:00前提交报名材料，尽调前且不晚于7月20日缴纳30万元人民币不计息保证金，按管理人要求在15日内完成尽调，8月10日前提交重整投资方案，被遴选确定后7个工作日内签署意向投资协议。这些属于当时的招募安排，不能据日历经过认定已执行完成。"
            },
            {
              "date": "2026-09-25",
              "text": "公司披露法院同意预重整期限延长一个月。审计评估已完成，但预重整方案仍在沟通确定。法院于9月18日收到延期申请，该日期并非已披露的批复作出日期或公司收件日期；后两项分别未明确、仅表述为近日。能否转入破产重整并避免破产清算仍存在不确定性。"
            }
          ],
          "business": [
            "陕西友帮主营医药中间体。2025年申请公告和2026年5月公告均披露康惠股份持股51%、弘福医药有限公司持股49%。康惠股份同时涉及股东、债权人和担保人身份，需分别关注股权投资回收、债权清偿和担保履行，不能将三类金额简单相加为确定损失或待回收资金。",
            "对意向产业投资人，可讨论恢复生产所需资金、投资支付安排、债务清偿方案及经营可行性；对康惠股份，可围绕历史债权与担保责任的处理开展方案分析。实际服务须确认客户身份、参与阶段、已有顾问安排及委托需求，不能由公开招募推定存在证券业务委托。",
            "陕西仁和万国律师事务所已被指定为临时管理人。法院决定书同时限制预重整期间的对外清偿、新增负债、对外担保和重大资产处置，相关融资或资产方案应先核对程序条件。历史报名期限已经过去，不能将原招募安排写成当前仍开放的机会。"
          ],
