          "summary": "宝钛股份2026年9月25日公告称，9月11日至9月24日已有十个交易日收盘价低于当期转股价格30.98元/股的85%，公告列示对应价格为26.33元/股。下修条件为任意连续三十个交易日中至少十五个交易日符合要求；触发后仍需董事会决定，提议下修还须股东会审议。本次是既有35亿元可转债的存续期提示，不代表已经触发、决定下修或新增融资；按公告约定，转股期自2026年12月30日起。",
