          "summary": "科华生物2026年9月29日公告，全资子公司科华（西安）生物工程有限公司近日收到陕西省药品监督管理局颁发的β人绒毛膜促性腺激素测定试剂盒（化学发光法）注册证，证号为陕械注准20262400170，有效期为2026年9月21日至2031年9月20日。产品用于早期妊娠诊断、妊娠监测及孕中期唐氏综合征风险评估，不用于肿瘤辅助诊断。公告未披露该产品实际销售情况，公司表示尚无法预测公告所列产品对未来营业收入的影响。",
          "stage": "全资子公司已收到医疗器械注册证",
          "depth": "brief",
          "coverage": "本事项有限历史研究；不等于观察池全量已更新。历史附件准确发布日期未核实，不依据文件URL或注册证号推定中选日期、首次获证日期；历史核查仅覆盖本轮提供的相关记录，不代表全历史。 现有两份材料不能证明上海母公司历史产品与西安子公司本次获证产品之间的注册、技术或生产承接关系，正文不作此认定。 历史中选结果未提供相关实际采购量、订单执行、销售收入或回款依据，不能把中选价格视作已成交记录。 本次公告未披露该产品投产、订单、销售收入及回款情况；未提供注册证原件，有效期和用途依据上市公司公告。 本轮仅补核已留存历史材料，未推进原发现窗口，未核查2026年9月30日研究截止后的新增经营进展。",
          "occurredAt": "详见本次动态与历史节点",
