              "date": "未标注，准确发布日期未核实",
              "text": "本轮补入的二十五省（区、兵团）体外诊断试剂省际联盟集中带量采购中选结果中，上海科华生物工程股份有限公司为同名试剂盒的生产企业和申报企业，注册证号为沪械注准20162400167，分组为B组。第101—102页列有五条规格记录，50人份、100人份及2×100人份包装对应中选价格分别为337.50元、675.00元及1350.00元。该记录属于上海母公司产品，不能据此认定西安子公司本次获证产品已经中选、销售或承接历史注册。"
