          "title": "投资者索赔进展：2名诉请被一审驳回，41名获准撤诉",
          "summary": "陕西广电网络传媒（集团）股份有限公司2026年9月24日披露，公司近期收到西安市中级人民法院一审判决，驳回2名投资者的全部诉讼请求；同期收到裁定，同意41名投资者撤诉，撤诉金额累计537.16万元。此前，2026年半年度报告列示截至报告出具日涉及134名投资者、索赔金额724.09万元，另明确截至2026年6月末相关预计负债为711.12万元。本次公告未披露两名投资者的诉请金额、判决生效状态及各批案件的逐一对应关系，不能直接推算剩余索赔规模，也不能将撤诉金额认定为等额利润增益。",
          "stage": "收到驳回2名投资者诉请的一审判决及准许41名投资者撤诉的裁定",
          "depth": "deep",
          "coverage": "本事项有限历史研究；不等于观察池全量已更新。本次公告未披露两名投资者的诉请金额、案号、裁判理由、具体收件日期、是否上诉及判决生效情况；候选仅表述已收到一审判决。 已查材料未提供81名、134名投资者与本次裁判涉及投资者的逐案对应清单及完整剩余索赔台账；不推算剩余人数、金额、结案比例或全历史累计规模。 撤诉是否伴随和解、支付或其他安排，以及相关预计负债后续调整金额，在已查材料中未找到明确披露；不将撤诉认定为免除全部责任或形成收益。 监管官网原页仍未留存。本轮通过公司公告转载内容核验了处罚对象、所涉年度、违法事实、认定理由及处罚决定；转载未列监管决定书独立落款日期，故仅使用公司收件日期，不将其等同于决定作出日，也不声称完成与监管官网原页的逐字比对。 本轮范围限于留存的本次公告、两期半年报相关内容、撤销风险警示申请公告及补入的处罚决定转载公告，不构成全部诉讼历史覆盖；候选仍须独立核查。",
