              "text": "2025年半年度报告列示81名投资者向公司提起虚假陈述责任纠纷诉讼，涉及金额617.63万元、预计负债617.63万元，阶段为已立案、未开庭。承担连带责任方栏列示公司部分时任董监高及会计师，该列示不等于法院已判定相关主体承担责任。"
