          "time": "",
          "title": "2024年配售资金上半年使用165.1百万港元，尚余421.3百万港元",
          "summary": "巨子生物2026年9月24日披露的中期报告显示，2024年5月配售及补足认购所募集的净资金约1,627百万港元，截至2026年6月30日累计使用1,205.7百万港元，尚未使用421.3百万港元。2026年上半年使用165.1百万港元，其中核心业务发展及生态圈布局使用141.4百万港元，补充流动资金及一般企业用途使用23.7百万港元。按各期披露合计比较，本轮资金上半年使用额较2025年同期减少约55.5%。公司表示拟定用途未变，计划未来2年内逐步使用，时间安排仍随市场和实际业务需要调整。本次披露属于2024年融资的后续使用进展。",
          "stage": "更新2024年融资截至2026年6月30日的募集资金使用情况",
          "depth": "deep",
          "coverage": "本事项有限历史研究；不等于观察池全量已更新。历史覆盖限定于已留存的2024年原方案、完成公告、2024年度业绩公告、2025年中报、2025年报及2026年中报；未单独核读2024年中报和2024年年报，不声称覆盖全部历史披露。2024年末基线使用已核读的年度业绩公告。 2025年中报存在0.1百万港元的分项、合计及期间衔接差异，已实际查看原页并保留原数；相关页面未披露具体原因，不能断言全部由舍入造成。 已核读的本事项披露未将剩余资金逐笔对应至存放机构、金融产品和未来付款计划，也未披露全部承配人的具体名称；不据此推断账户、投资产品或业务委托需求。 未来2年属于可调整的预期时间表，现有材料不足以确定具体用尽日期或认定正式延期。",
