          "history": [
            {
              "date": "2024-05-17",
              "text": "公司公告披露，5月16日交易时段后与Juzi Holding Co., Ltd及配售代理订立协议，拟以每股49.40港元配售卖方持有的33,220,000股现有股份，再由卖方按相同价格认购同等数量新股。预计净募集资金约1,627百万港元，90%用于核心业务发展及生态圈布局，10%用于补流及一般企业用途；当时交易仍受完成条件约束。"
            },
            {
              "date": "2024-05-24",
              "text": "完成公告确认，现有股份配售于5月21日完成，补足认购于5月24日完成，均为33,220,000股、每股49.40港元，公司自认购收取净款约1,627百万港元。卖方补足认购后的持股数量恢复至581,104,935股，持股比例由交易前58.40%降至56.52%。"
            },
            {
              "date": "2025-03-26",
              "text": "2024年度业绩公告披露，本轮资金2024年使用330.9百万港元，年末尚余1,296.1百万港元；当时的使用安排表述为未来3年内按实际业务情况逐步使用，并保留时间表可变的限定。"
            },
            {
              "date": "2025-09-23",
              "text": "2025年中期报告披露，本轮资金上半年使用合计371.0百万港元，截至6月30日累计使用701.9百万港元、尚余925.1百万港元；时间安排表述为未来2年内逐步使用。该表分项与合计存在0.1百万港元差异，本文保留披露原数。"
            },
            {
              "date": "2026-04-29",
              "text": "2025年报披露，本轮资金2025年全年使用709.7百万港元，年末尚余586.4百万港元，其中核心业务用途余额509.2百万港元、补流及一般企业用途余额77.2百万港元。709.7百万港元为2025年当年使用额，并非自融资完成起的累计使用额。"
            },
            {
              "date": "2026-09-24",
              "text": "2026年中期报告更新截至6月30日的使用情况：期初未使用586.4百万港元，上半年使用165.1百万港元，期末未使用421.3百万港元；累计使用1,205.7百万港元。公司继续表述用途未变、计划未来2年内逐步使用。"
            }
          ],
          "business": [
            "公司本轮资金的上半年使用额由2025年同期371.0百万港元降至2026年的165.1百万港元。可以围绕剩余用途、品牌推广和研发支出节奏，与公司讨论资金预算及期限匹配；上述变化只反映这轮募集资金的使用节奏，不能直接推导公司整体投资或经营支出同比变化。",
            "截至2026年6月30日尚未使用的421.3百万港元仍有指定用途。是否存在阶段性资金管理需求，需要公司确认具体存放安排、预计付款时间及可运用条件；该余额不能直接视为可购买金融产品或待争取的资金。",
            "2024年交易已有高盛（亚洲）有限责任公司担任整体协调人及配售代理、中国国际金融香港证券有限公司担任财务顾问。补足卖方出售旧股后认购同等数量新股，公司取得认购款；不宜将公司融资净额解释为卖方可自由支配的减持所得。本次披露本身也不足以证明存在新的融资委托或中介遴选。"
          ],
