          "summary": "巨子生物控股有限公司（02367.HK）2026年9月24日披露的中期报告显示，2026年上半年支付予公司股东的股息为人民币1,285,087千元，即12.85087亿元，与报告列示的2025年度末期及特别股息获批准总额一致。两项股息分别为每股人民币0.5390元和0.6714元，合计1.2104元，于2026年5月28日获股东大会批准，公告安排于6月25日或前后派付。中报确认的是上半年支付情况，并非9月新增宣派；公司董事不建议派付2026年中期股息。",
