          "summary": "炼石航空2026年9月23日披露，董事会于9月22日以9票同意通过向全资下属公司Gardner Aerospace Limited增资3,600万英镑的议案，按公告采用汇率约合人民币32,415.84万元。资金来自公司自有资金，先向境内加德纳航空科技有限公司增资3.42亿元人民币，再经香港炼石投资有限公司逐层投入英国加德纳，各层金额不重复累计。用途为补充日常经营流动资金，包括但不限于偿还存量借款。英国加德纳2026年6月末未经审计净资产为-8,706.89万元，上半年净亏损6,571.04万元。历史上，上市公司2025年重整已引入12.38亿元投资款，并代加德纳清偿一笔3,400万美元等值人民币外部债务、成为其债权人；这些历史处理不等于本次增资，也不意味着加德纳全部债务消失。本次无需股东会批准，但境内备案、外汇审批及境外注册变更等手续尚待办理，现有材料未证明本次出资到账。",
