          "title": "获批1亿元关联保理额度，两类业务期限与前期不同",
          "summary": "陕鼓动力2026年9月22日披露，9月20日董事会批准公司与西安长青恒业商业保理有限责任公司开展总额不超过10,000万元的应收账款保理业务，额度自董事会审议通过之日起一年内有效，无需提交股东会。长青保理为控股股东陕鼓集团的全资子公司。本次下游应收账款保理为无追索权、期限不超过3年；上游供应商应收公司账款的保理为有追索权、期限不超过6个月。已核实的2025年前期授权覆盖公司及各分子公司，额度不超过5.07亿元，两类业务期限分别不超过2年、1年；因主体范围不同，不能将本次额度直接解释为同口径缩减。公告所述过去12个月累计业务634.13万元不代表本次新增到账或当前余额，具体业务金额、费率及期限以合同为准。",
