          "summary": "陕鼓动力2026年10月10日公告，拟发行股份购买陕西秦风气体股份有限公司四名少数股东合计持有的36.06%股权，相关工作仍在推进，完成后将再次提交董事会审议，尚需股东会及有权监管机构批准、核准或同意注册。与9月11日公告相比，本次未披露新增审批、发行或交割完成节点。7月预案拟将公司对秦风气体的持股比例由63.94%提升至100%，当时交易作价及各卖方具体股份对价尚未确定，10月公告未更新这些条款；预案披露恒博隆所持标的股权存在质押，其解除承诺不能视为已经履行。",
          "stage": "此前预案已获董事会通过；截至本公告披露日仍推进相关工作，尚待再次董事会、股东会及有权监管机构批准、核准或同意注册",
          "depth": "deep",
          "coverage": "本事项有限历史研究；不等于观察池全量已更新。本次仅使用已留存的7月11日预案、9月11日及10月10日进展公告，未联网，不宣称覆盖该交易全部历史披露。 8月11日进展公告原件不在本轮输入中，未独立核读其内容；历史比较明确限定为已核读的7月预案、9月与10月公告，不认定7月至10月全部条款始终未变。 交易作价、逐方具体股份对价及最终发行数量在预案时尚未确定，9月及10月公告未补充。本文仅呈现预案安排和已披露阶段，不推算交易金额、卖方收益或每股收益增厚。 恒博隆质押的具体数量、质权人及实际解除情况在本次所核读材料中未见明确披露；解除承诺及其时点已保留于正文，不据此确认当前不存在权利限制或具备交割条件。 留存原件实际取得时间晚于输入记录中的原研究截止时刻2026年10月15日17:07:38；本候选使用本轮补入材料，不声称在该时刻已经完成核读。公告事实截至各自披露日，未核实其后状态。",
