          "business": [
            "秦风气体在预案签署时已是陕鼓动力合并报表范围内的控股子公司。本次交易拟收购剩余少数股东权益，完成后持股比例提升至100%。业务理解重点是对既有工业气体板块的权益整合；具体利润增厚及每股收益影响仍需结合最终作价、发行数量和重组报告书评估。",
            "预案披露，秦风气体业务包括空分气体、合成气体、焦炉煤气综合利用及液体零售，采用长期供气协议为主、零散订单补充的经营模式。理解其价值应关注持续供气业务及经营质量，不能仅凭收购比例推算交易估值或收益。",
            "围绕上市公司可讨论正式方案、估值和发行实施事项；围绕四名售股股东可讨论对价股份登记、锁定及后续持股管理。恒博隆还涉及交割前解除标的股权质押的承诺核验。是否存在新增服务需求、已有中介安排及可参与范围均须向相关主体确认，不能将拟取得股份写成已到账现金。"
          ],
