          "summary": "源杰科技2026年10月16日披露，光电通讯半导体芯片和器件研发生产基地二期项目的土建工程、部分洁净室及相关配套设施已完成建设，首批生产设备预计近期开始进厂，后续进行设备调试，预计2026年底至2027年初开始形成产能。项目投资总额约12.51亿元人民币，以实际投入为准，不能视为本次新增投入或已支付金额。本次披露尚不代表项目全部竣工或已经形成产能，实施及达产进度仍存在不确定性。",
