          "depth": "deep",
          "coverage": "本事项有限历史研究；不等于观察池全量已更新。本轮仅核读2026年2月10日原投资公告及10月16日进展公告，未覆盖本项目全部历史披露；不据此断言期间没有其他进展。 未取得3月2日股东会决议原件；审议通过事实由10月16日公司公告明确回溯确认，未扩展主张当日表决明细。 两份已核公告未披露累计实际投入、实际贷款金额、贷款银行、贷款到账或付款明细，也未披露量化产能指标；不据此推算融资缺口、投入完成比例或收益。 原18个月建设期未明确起算日期，最新公告预计开始形成产能的时间不等同于项目整体竣工或全面达产时间。 使用本轮留存及补入原件，实际取得时间分别为2026年10月16日07:57:06和09:18:15.707968，均晚于输入所列07:56研究截止；本候选属于补证结果，不证明材料在07:56前已公开可见，未推进原发现窗口或来源覆盖。",
