            "电影公司是公告明确的一致行动人，其竞得160万股意味着旅游投资集团直接持股减少与一致行动人合计权益变化需要分别观察。公告关于过户后旅游投资集团持股21.70%的测算同时包含另案300万股，不能将该比例全部归因于本次800万股。",
