          "summary": "农心科技2026年10月14日公告，公司股票于10月12日至13日连续两个交易日收盘价格涨幅偏离值累计超过20%，构成股票交易异常波动。公司称，经自查及向控股股东、实际控制人核实，截至公告披露日不存在应披露而未披露的重大信息，主营业务及经营情况未发生重大变化；油化工、煤化工价格波动及可能出现的厄尔尼诺现象对公司经营的直接影响尚不能判断，并提示短期上涨过快可能出现下跌风险。",
