          "summary": "炬光科技2026年9月22日披露，2026年限制性股票激励计划预留授予对象名单于9月11日至20日在公司内部公示，期间未收到异议，无反馈记录；董事会薪酬与考核委员会认为对象资格合法、有效。对应批次的授予日为9月10日，以259.51元/股向15名骨干员工授予28.62万股第二类限制性股票，9月11日披露时剩余预留43.10万股。本次进展为公示结果及资格核查，不代表新增授予，也不代表股份已经归属、登记或上市流通。",
          "stage": "预留授予名单公示期满无异议，薪酬与考核委员会发表核查意见",
          "depth": "deep",
          "coverage": "本事项有限历史研究；不等于观察池全量已更新。公开预留名单及授予公告仅披露15名骨干员工的合计权益，未逐人列示姓名、具体职务及分配数量，无法据此计算个人认购资金或权益。 草案未给出个人绩效分数与归属比例的具体映射，也不提供未来考核结果，不能据此计算个人实际可归属数量。 本文资料范围未覆盖2026年9月22日之后的新增进展；43.10万股剩余预留数量仅代表9月11日披露口径，不代表研究截止时的最新余额。",
