              "value": "本批次按30%、30%、40%分三期归属。公司层面人效系数X与费用率系数Y取较高值作为归属比例W，并非要求两项同时达到目标值；个人实际归属数量还须乘以个人归属比例S，并满足12个月以上任职期限及其他归属条件。因考核不能归属的部分作废失效，不得递延。"
