          "title": "调整2024年股权激励：授予价降至43.78元/股，未归属数量调整为55.0135万股",
          "summary": "源杰科技2026年10月14日披露，董事会于10月13日审议通过2024年限制性股票激励计划价格及数量调整。因2025年度、2026年半年度权益分派实施完毕，首次及预留授予价格由65.56元/股调整为43.78元/股，已授予尚未归属数量由37.9770万股调整为55.0135万股，其中首次部分38.4560万股、预留部分16.5575万股。这是既有权益调整，不是新授予或实际归属；55.0135万股为调整议案口径，未扣除同日另案作废的3,042股。",
          "stage": "2026年10月13日董事会审议通过授予价格及已授予尚未归属数量调整；非新授予",
          "depth": "deep",
          "coverage": "本事项有限历史研究；不等于观察池全量已更新。资料覆盖本次调整公告、董事会决议及法律意见书，2025年7月和9月相关文件，以及2025年年报相关页。2024年首次授予采用后续公告回溯记录，未覆盖该计划全部历史文件。 2026年两次权益分派实施公告及银行凭证未单独查验；实施完成采用公司调整公告和法律意见书所载核验结果。 年报相关页未逐项解释177,380股可归属量与176,980股实际归属量的差异，也未给出预计未来可行权数量与本次未归属基数之间的逐人变化。实际执行记录能够衔接本次基数，但不能据估计差额推定额外作废或归属。 同日预留归属材料证明归属条件成就及批准办理，不提供该批次完成登记的证据；员工证券账户、经纪服务和后续资金安排未在已查材料中明确。",
          "occurredAt": "详见本次动态与历史节点",
