          "important": true,
          "production": true,
          "prototype": false,
          "history": [
            {
              "date": "2022-11-15",
              "text": "回购报告书披露，2022年11月7日董事会通过以自有资金集中竞价回购股份的方案，金额为人民币5亿至10亿元，价格上限32.88元/股，期限自董事会审议通过之日起12个月内。股份拟用于员工持股计划或股权激励，回购完成后3年内未完成用途或未全部使用的部分将依法注销。"
            },
            {
              "date": "2023-07-18",
              "text": "因实施2022年度权益分派，公司将回购价格上限由32.88元/股调整为24.44元/股，自2023年7月18日起生效。分派以扣除已回购股份后的股本为基数，每10股派现11.20元（含税）、转增3股；调整后的预计回购数量为24,596,170股至45,054,435股，仍以期满实际数量为准。"
            },
            {
              "date": "2023-11-02",
              "text": "截至2023年10月31日累计回购30,983,837股，支付578,216,994.50元，含印花税、交易佣金等交易费用；当时回购仍在实施。"
            },
            {
              "date": "2023-11-08",
              "text": "实施结果公告披露，2023年11月7日回购期限届满，实际回购32,543,837股，使用资金600,069,500.05元（含交易费用）；披露最高价21.03元/股、最低价13.95元/股、均价18.44元/股。公司称已按披露方案完成回购，股份继续作为未来员工持股计划或股权激励的股票来源。"
            },
            {
              "date": "2026-08-07",
              "text": "公司披露8月6日董事会通过用途变更议案，将32,543,837股尚未使用的回购股份改为注销并减少注册资本；该披露时点尚需股东会审议。"
            },
            {
              "date": "2026-08-25",
              "text": "股东会决议公告披露，8月24日召开的第三次临时股东会通过用途变更、注销减资议案及章程修订议案，两项均为特别决议。"
            },
            {
              "date": "2026-08-25",
              "text": "公司披露减资债权人通知，债权人可自接到通知起30日内、未接到通知者自公告披露日起45日内，要求清偿债务或者提供相应担保。"
            }
          ],
          "business": [
            "本次进展是既有库存股用途变更后的注销落地，2023年已支付的回购资金属于历史支出。公司层面的后续沟通可围绕工商变更、备案及股份管理衔接展开，具体办理进度和服务需求仍待公司确认。",
            "原拟用于员工持股或股权激励的股份已经注销，不能据此认定公司正在实施新的激励授予或存在员工认购需求。"
          ],
          "details": [
            {
              "label": "本次阶段",
              "value": "股份注销于2026年10月12日完成。公告列示注册资本由5,052,792,571元变更为5,020,248,734元，同时明确工商变更登记与备案将后续办理。"
            },
            {
              "label": "计划与执行金额",
              "value": "原计划使用自有资金人民币5亿至10亿元；期满实际使用600,069,500.05元，含交易费用，比下限高100,069,500.05元，比上限低399,930,499.95元。与上限之差不代表尚待实施的回购资金。"
            },
            {
              "label": "数量比较口径",
              "value": "原报告书按32.88元/股测算预计回购1,520.68万至3,041.36万股；权益分派调价后，结合已回购情况重新测算为24,596,170股至45,054,435股。两者均为测算数量，不能把期满实际32,543,837股直接与原测算上限比较后认定超额回购。"
            },
            {
              "label": "价格调整口径",
              "value": "调价公告使用差异化分红后按总股本摊薄的每股现金红利及股份变动比例，并将中间值分别取近似数1.11元/股和0.30，再计算（32.88－1.11）÷（1＋0.30）≈24.44元/股。24.44元/股为公告明确的调整后上限，不表述为保留全部中间精度重算的结果。"
            },
            {
              "label": "均价口径",
              "value": "期满公告披露均价18.44元/股；含费资金总额除以披露股数约为18.438806元/股，保留两位小数同为18.44元/股。该复算不等同于不含费成交均价。"
            },
            {
              "label": "债权人程序",
              "value": "截至2026年10月12日公告披露日，公司称公示期已满45天，期间未出现债权人申报债权并要求清偿债务或者提供相应担保的情况。"
            },
            {
              "label": "股本表使用边界",
              "value": "注销公告注明，股本结构变动情况以注销完成后中国证券登记结算有限责任公司上海分公司出具的股本结构表为准。本文列示公司公告数据，未取得该登记机构原始证明。"
            }
          ],
