          "summary": "陕鼓动力2026年10月9日提供的股东会议案，继续提交陕鼓高端装备产业创新研究中心建设方案：由上市公司实施，拟投资不超过人民币67,262万元，最终投资金额以实际投资为准；资金来源为企业自筹，建设周期34个月。该方案已于9月29日获董事会通过，拟提交10月16日股东会审议。10月9日材料与9月30日专项公告所列投资上限、地点、建筑面积、周期及资金来源一致，属于同一方案的会议配套。按研究截止2026年10月15日17:07:38及本轮已取得资料，尚无股东会批准、开工或实际投入金额的证据。",
          "stage": "2026年9月29日董事会通过，9月30日披露；10月9日提供股东会议案，拟提交10月16日股东会审议，尚未取得股东会批准或开工依据",
          "depth": "deep",
          "coverage": "本事项有限历史研究；不等于观察池全量已更新。已完成6条围绕项目名称、建设地址及前期建设安排的限定官方来源检索，未取得9月29日前同项目的立项、投资安排或变更原文。历史对照限于已取得的9月披露方案与10月会议议案，不声称该项目此前不存在。 本轮原件未披露实际投资、付款、融资到账、明确开工日期及建设周期起算日；不将拟投资上限视为实际投入，也不以34个月推算竣工日期。 本轮未取得规划审批、施工许可或股东会批准的完成依据。研究截止为2026年10月15日17:07:38，不能用截止之后的日历进程替代实施证据。 发现窗口仍为2026年10月4日至10月9日，留存原件实际取得时间为10月9日；本轮历史检索不代表完整推进了其后的公告发现覆盖。 公告提出的经营改善与土地价值提升属于预期影响，未提供量化收益测算；本稿不据此推算项目回报或公司估值。",
