              "text": "公司披露，9月29日董事会审议通过研究中心投资议案，同意9票、反对0票、弃权0票，并同意提交股东会。专项公告明确公司为实施主体，拟自筹不超过67,262万元建设，建设周期34个月；当时仍须提交股东会审议。"
