            {
              "date": "2026-09-30",
              "text": "同日会议通知将研究中心投资列为第一项议案，安排于10月16日召开的2026年第三次临时股东会审议。该通知证明会议安排，不证明议案已经获得股东会批准。"
            },
            {
              "date": "2026-10-09",
              "text": "公司提供会议议案，重列同一研究中心的投资上限、实施主体、建设地点、建筑面积、建设周期和自筹资金安排，并提请股东审议。上述项目参数与9月30日专项公告一致；本次材料未披露新增投资额度或实际投入金额。"
            }
