          "prototype": false,
          "history": [
            {
              "date": "2026-05-29",
              "text": "公司披露，5月28日独立董事专门会议及董事会审议通过投资事项，拟以自有资金不超过3000万元参与重庆欣晖B+轮融资。标的当时计划本轮融资不少于16000万元，用于设备采购、工程建设尾款支付及日常营运资金等；其他投资机构尚在投资决策中，交易能否完成仍存在不确定性。"
            },
            {
              "date": "2026-08-08",
              "text": "公司披露已于近日与其他市场化投资方及重庆欣晖签署B+轮融资相关协议，约定出资3000万元取得2.0157%股权，其中53.8826万元计入新增注册资本，其余计入资本公积。当时资金交割及工商变更尚未完成。"
            },
            {
              "date": "2026-10-10",
              "text": "公司披露最终实际出资3000万元，取得重庆欣晖2.0157%股权，B+轮融资资金交割及工商变更登记已于近日完成。该日期为公告日期，不替代具体交割或登记日期。"
            }
          ],
          "business": [
            "重庆欣晖从事半导体关键材料及部件研发、生产和销售，主要产品包括碳化硅部件、硅部件。西安奕材披露的投资目的包括拓宽业务布局、促进产品协同和提升客户服务能力。业务跟踪可围绕上市公司作为少数股东的投后管理、协同落实和投资退出安排展开；这些属于可与客户讨论的事项，具体服务需求及已有服务安排仍待确认。",
            "8月协议摘要列示投资方享有优先购买权、共同出售权、领售权、反稀释权、回购权和优先清算权等权利，但未展开各项权利的触发条件。少数股权及合同保护不能据此解释为收益保证；标的持续亏损，后续仍需观察经营改善与协议权利的实际可执行性。",
            "重庆欣晖5月披露的融资用途涉及设备采购、工程建设尾款及营运资金。若讨论标的后续融资服务，应先向其确认项目进度、资金使用及新增融资安排；本次3000万元已完成出资，不能视为尚待募集的资金需求。"
          ],
