          "summary": "天和防务2026年10月13日公告，全资子公司南京彼奥与江苏银行南京分行签订无还本续贷协议及流动资金借款合同，公司及控股股东、实际控制人贺增林及其配偶分别签署连带责任保证书，为合同项下人民币1000万元债权提供担保。截至公告披露日，上述借款尚未放款，公司对南京彼奥的担保余额在本次担保前后均为人民币5990万元。",
