          "summary": "金利华电2026年9月18日披露，拟通过发行股份及支付现金购买西安中科西光航天科技集团有限公司82.50%股权，并向控股股东山西红太阳旅游开发有限公司发行股份募集配套资金。截至该公告披露日，具体交易方案仍在协商完善，尽职调查、审计及评估尚未完成，最终方案以后续重组报告书为准。交易尚需董事会再次审议、股东会批准、深交所审核通过及中国证监会同意注册后方可正式实施。",
          "stage": "预案披露后的定期进展；尽职调查、审计及评估尚未完成",
          "depth": "deep",
