          "summary": "晨曦航空2026年9月24日披露，使用闲置募集资金购买中国银行人民币结构性存款2,100万元，产品为保本浮动收益型，起息日为9月24日，约定到期日为10月26日，预期年化收益率为0.6000%—1.7100%。截至该公告披露日，相关现金管理未到期余额为2,100万元，含本次购买。2026年现金管理授权上限维持5,000万元，额度内可滚动使用，期限从原到期日起延长12个月。资金来自2022年向特定对象发行股票募集资金，对应直升机研发中心项目。本稿现金管理执行资料截至2026年9月24日，未取得本次产品赎回及实际收益资料。",
