              "text": "公司披露已购买2,100万元中国银行人民币结构性存款，该日起息，约定10月26日到期。截至公告披露日，闲置募集资金现金管理未到期余额2,100万元，含本次购买。公告所列九笔历史产品均标注全部赎回，并披露逐笔收益；这些收回状态不倒填至各产品起息日。"
