          "business": [
            "资金主体为上市公司，资金性质为暂时闲置募集资金，对应直升机研发中心项目。结合项目建设及人员费用安排，可与公司讨论支出节奏、现金管理产品期限匹配和到期本金收益核对；后续实际可用金额、闲置期限及配置意向仍需公司确认。",
            "中国银行已有实际产品承接记录，国信证券已有保荐安排；历史募集资金监管协议还涉及招商银行及中国银行相关支行。既有合作不能写成尚待确定的服务机会，5,000万元授权上限与2,100万元未到期余额之差也不能直接视为新增可配置资金。",
            "历史曾发生结构性存款未成功认购、资金实际按协定存款存放的情况，跟踪重点应包括认购确认、资金存放状态和实际收益入账。本次约定到期日与预期年化收益率均不代表已赎回或已实现收益。",
            "授权公告对产品安全性、流动性、单项期限、质押及专用账户用途设有限制，并限制证券投资及以股票、利率、汇率等衍生品为主要投资标的的理财产品。具体服务方案仍须结合公司需求和执行时有效规则确认。"
          ],
