          "summary": "西财金服2026年8月18日披露，西安中科光凝科技有限公司近日完成数千万元A+轮融资，由盈富泰克（北京）科技创新创业投资基金（有限合伙）、西安西高投繁星投资基金合伙企业（有限合伙）联合投资。资金主要用于量子精测等领域专用超快激光装备研发，以及半导体领域激光精密加工设备技术升级。文章未披露精确完成日期、各方出资额和本轮估值。",
