              "text": "西安财金2026年科技创新公司债券募集说明书回溯披露：截至2025年6月末，人才基金已投资项目表中，中科光凝对应投资金额500万元、股权比例3.33%，决策时间为2023年10月31日。这是基金单项投资记录，不能认定为整轮融资金额，也不能把决策日当作交割日或披露日。"
